gemm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Split-K GEMM for C[M,N] = A[M,K] * B[K,N], row-major A/B/C.
// Optimization: 3-stage cp.async shared-memory pipeline for aligned/full tiles,
// with a fallback to the original double-buffered kernel for general shapes.
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 32;
constexpr int THREADS = 1024;
constexpr int THREADS_FAST = 256;
constexpr int STAGES = 3;
__device__ __forceinline__ void async_commit() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.commit_group;");
#endif
}
template <int N>
__device__ __forceinline__ void async_wait() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.wait_group %0;" :: "n"(N));
#endif
}
__device__ __forceinline__ void cp_async_16(void* dst, const void* src) {
#if __CUDA_ARCH__ >= 800
  unsigned saddr = (unsigned)__cvta_generic_to_shared(dst);
  asm volatile("cp.async.ca.shared.global [%0], [%1], 16;" :: "r"(saddr), "l"(src));
#else
  *reinterpret_cast<float4*>(dst) = *reinterpret_cast<const float4*>(src);
#endif
}
// Fast tile loader: only launched when all tiles are full and 16B aligned.
__device__ __forceinline__ void load_k_tile_async(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ sA_raw,
    float* __restrict__ sB_raw,
    int m_start, int n_start, int kt,
    int M, int N, int K)
{
  const int tid = threadIdx.x;
  #pragma unroll
  for (int idx = tid; idx < (BM * BK) / 4; idx += THREADS_FAST) {
    int mi = idx >> 3;
    int ki = (idx & 7) * 4;
    const float* g = A + (int64_t)(m_start + mi) * K + kt + ki;
    cp_async_16(&sA_raw[mi * BK + ki], g);
  }
  #pragma unroll
  for (int idx = tid; idx < (BK * BN) / 4; idx += THREADS_FAST) {
    int ki = idx >> 5;
    int ni = (idx & 31) * 4;
    const float* g = B + (int64_t)(kt + ki) * N + n_start + ni;
    cp_async_16(&sB_raw[ki * BN + ni], g);
  }
}
