  float* sB_base = smem_raw + STAGES * BM * BK;
  const int tx = tid & 15;
  const int ty = tid >> 4;
  const int m0 = ty * 8;
  const int n0 = tx * 8;
  float acc[8][8];
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    #pragma unroll
    for (int j = 0; j < 8; ++j) acc[i][j] = 0.0f;
  }
  #pragma unroll
  for (int s = 0; s < STAGES - 1; ++s) {
    int kt = k_start + s * BK;
    if (kt < k_end) {
      load_k_tile_async(A, B, sA_base + s * (BM * BK), sB_base + s * (BK * BN), m_start, n_start, kt, M, N, K);
