    for (int kk = 0; kk < BK; ++kk) {
      float a_frag[8];
      #pragma unroll
      for (int i = 0; i < 8; ++i) a_frag[i] = sA[(m0 + i) * BK + kk];
      float4 bv0 = *reinterpret_cast<const float4*>(&sB[kk * BN + n0]);
      float4 bv1 = *reinterpret_cast<const float4*>(&sB[kk * BN + n0 + 4]);
